const chanYtd=(()=>{const v=chanYear.map(x=>Math.round(x*YTD_SHARE));const d=YTD_REV-sum(v);v[0]+=d;return v;})();
const chanLabels=[...CHANNELS7.map(c=>CH_SHORT[c]),'Прочие клиенты'];
